import game.*;import ui.*;import java.awt.*;import java.awt.event.*;import java.awt.image.*;import java.nio.file.*;import java.util.*;import java.util.List;import javax.imageio.*;
/** Actual UI input, cached illustrated artwork, responsive layout and authoritative clocks. */
public class Phase2UITest extends JourneyHomeTest {
 static int pixels(BufferedImage image){int n=0;for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++)if((image.getRGB(x,y)>>>24)!=0)n++;return n;}
 static void moveMouse(GamePanel p,Point point){var e=new MouseEvent(p,MouseEvent.MOUSE_MOVED,0,0,point.x,point.y,0,false);for(var l:p.getMouseMotionListeners())l.mouseMoved(e);}
 static Rectangle ink(BufferedImage image){int l=image.getWidth(),r=-1,t=image.getHeight(),b=-1;for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++)if((image.getRGB(x,y)>>>24)>32){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);}return new Rectangle(l,t,r-l+1,b-t+1);}
 public static void main(String[]args)throws Exception{
  ChristmasUI.prepare();int assets=0;try(var files=Files.list(Path.of("assets/ui/phase2"))){for(var p:files.filter(n->n.toString().endsWith(".png")).toList()){
   var im=ImageIO.read(p.toFile());check(im!=null&&im.getColorModel().hasAlpha(),"Real RGBA artwork "+p);int transparent=0,solid=0;Set<Integer> colors=new HashSet<>();
   for(int y=0;y<im.getHeight();y+=2)for(int x=0;x<im.getWidth();x+=2){int c=im.getRGB(x,y);if((c>>>24)==0)transparent++;if((c>>>24)>240){solid++;colors.add(c);}}
   check(transparent>0&&solid>100&&colors.size()>300,"Detailed illustrated content and real transparent surroundings "+p);assets++;
  }}check(assets==15,"Exact three frames, six buttons, five icons and wax seal");
  for(int i=0;i<5;i++){var im=ChristmasUI.icon(i);check(im.getWidth()==48&&im.getHeight()==48&&pixels(im)>200,"Cached recognizable icon "+i);if(i>0)check(!Arrays.equals(im.getRGB(0,0,48,48,null,0,48),ChristmasUI.icon(i-1).getRGB(0,0,48,48,null,0,48)),"Five distinct skill identities");}
  check(ChristmasUI.frameImage("parchment",650,206)==ChristmasUI.frameImage("parchment",650,206),"Repeated layout reuses image cache");
  for(int[] size:new int[][]{{800,600},{1270,720},{1024,768}}){
   int w=size[0],h=size[1];var overlay=new StoryOverlay();String text="Christmas is coming. In the Last Workshop, three presents are ready for familiar faces in The Last Village. Santa gathers his gifts and prepares to bring a little joy to the winter.";overlay.start(text,"Watch its claws and crystalline breath. Dodge the marked attacks, then strike during recovery.");
   var im=new BufferedImage(w,h,2);var g=im.createGraphics();overlay.draw(g,w,h);g.dispose();var bounds=ink(im);check(Math.abs(bounds.getCenterX()-w/2.0)<3&&Math.abs(bounds.getCenterY()-h/2.0)<3,"Content-responsive story card centered at "+w);
   check(bounds.width<=w-40&&bounds.height<h/2,"Compact content with bounded viewport margins");int frame=overlay.getFrames();for(int i=0;i<20;i++){g=im.createGraphics();overlay.draw(g,w,h);g.dispose();}check(overlay.getFrames()==frame,"Paint never advances approved cinematic clock");overlay.advance();check(overlay.isActive(),"Existing page advance");overlay.advance();check(!overlay.isActive(),"Existing bounded page completion");
   var p=playing();p.setSize(w,h);tick(p,180);var objective=(QuestGuidance.Objective)call(p,"currentObjective");var box=HUD.questBounds(objective,chapter(p),w,h);check(box.x==14&&box.getMaxY()==h-14&&box.y>=114,"Original bottom-left tracker anchor");
   var skill=new AbilityHUD();for(int i=0;i<5;i++)check(!box.intersects(skill.bounds(w,h,i))&&new Rectangle(0,0,w,h).contains(skill.bounds(w,h,i)),"Skill and quest layout separated "+i);
   var protectedActor=new Rectangle(w/2-51,h/2+30,102,110);var marker=ChristmasUI.directionPosition(w/2,h-90,box,w,h,protectedActor);var direction=new Rectangle(marker.x-84,marker.y-12,168,44);check(!direction.intersects(AbilityHUD.stripBounds(w,h))&&!direction.intersects(box)&&!direction.intersects(protectedActor),"Direction label clears relocated tracker, skills and Santa");
   var edge=ChristmasUI.directionPosition(55,h-90,box,w,h,protectedActor);check(edge.y+32<=box.y,"Left-edge objective prompt clears bottom-left tracker");
   int sequence=santa(p).getAttackSequence();boolean collapsed=chapter(p).trackerCollapsed();var toggle=HUD.questToggleBounds(objective,chapter(p),w,h);mouse(p,toggle.x+toggle.width/2,toggle.y+toggle.height/2);check(chapter(p).trackerCollapsed()!=collapsed&&santa(p).getAttackSequence()==sequence,"Actual tracker click toggles without combat");var expanded=HUD.questBounds(objective,chapter(p),w,h);check(expanded.x==14&&expanded.getMaxY()==h-14&&!expanded.intersects(AbilityHUD.stripBounds(w,h)),"Toggle retains bottom-left anchor and skill clearance");
   im=new BufferedImage(w,h,2);g=im.createGraphics();g.setFont(new Font("Dialog",Font.PLAIN,13));var notice=ChristmasUI.notificationBounds(g,"Iris received a Christmas present. 1/3",w,h,false);check(notice.y+notice.height<skill.bounds(w,h,0).y&&notice.x>box.x+box.width,"Shared notice lane clears both HUD groups");var actor=new Rectangle(w/2-51,h/2+30,102,110);var safe=ChristmasUI.safeNotificationBounds(g,"Town road cleared. Reach the Spirit Tree to the south.",w,h,false,actor);check(!safe.intersects(actor)&&safe.getMaxY()<skill.bounds(w,h,0).y,"Notice avoids Santa and nearby prompts under boss camera framing");g.dispose();
   g=im.createGraphics();ChristmasUI.notification(g,"Christmas returns. The sleigh is waiting in the plaza. [E] Return Home.",w,h,false);g.dispose();check(pixels(im)==0,"Specific persistent return banner draws no pixels");
   g=im.createGraphics();ChristmasUI.notification(g,"Toby's Gift Found! Return the Gift to Toby.",w,h,false);g.dispose();check(pixels(im)>2000,"Other notifications retain original information");
   tap(p,KeyEvent.VK_ESCAPE);check(p.getState()==GamePanel.State.PAUSED,"Existing pause input");int sx=santa(p).getX(),sy=santa(p).getY();var abilities=(AbilitySystem)field(p,"abilitySystem");int cooldown=abilities.skills().starCooldown();tap(p,KeyEvent.VK_2);tick(p,60);check(santa(p).getX()==sx&&santa(p).getY()==sy&&abilities.skills().starCooldown()==cooldown,"Pause blocks skill and movement clocks");
   var ready=render(p);moveMouse(p,new Point(w/2,h/2+60));var hovered=render(p);check(!Arrays.equals(ready.getRGB(0,0,w,h,null,0,w),hovered.getRGB(0,0,w,h,null,0,w)),"PNG selected state follows real pause hover");mouse(p,w/2,h/2+60);check(p.getState()==GamePanel.State.PLAYING,"Existing resume mouse hitbox");tap(p,KeyEvent.VK_ESCAPE);tap(p,KeyEvent.VK_ENTER);check(p.getState()==GamePanel.State.PLAYING,"Enter resumes unchanged");tap(p,KeyEvent.VK_ESCAPE);tap(p,KeyEvent.VK_ESCAPE);check(p.getState()==GamePanel.State.PLAYING,"Escape resumes unchanged");
   var manager=(DialogueManager)field(p,"dialogueManager");manager.startNarrative(List.of(new DialogueLine("Santa",Portrait.Kind.SANTA,text),new DialogueLine("Elias",Portrait.Kind.ELIAS,"The burden is lifting. Bring its last light back to the Spirit Tree.")));tap(p,KeyEvent.VK_2);check(manager.isActive()&&abilities.skills().starCooldown()==cooldown,"Dialogue skill isolation");tap(p,KeyEvent.VK_E);check(manager.isActive()&&manager.getActiveDialogue().getCurrentLineNumber()==2,"E advances original dialogue pages");tap(p,KeyEvent.VK_E);check(!manager.isActive(),"E closes and restores controls");p.stopGame();
  }
  check(AbilitySystem.BELL_DAMAGE==75&&AbilitySystem.BELL_COOLDOWN==90&&SantaSkills.STAR_DAMAGE==18&&SantaSkills.STAR_COOLDOWN==60&&SantaSkills.BOMB_DAMAGE==110&&SantaSkills.BOMB_RADIUS==130&&SantaSkills.COOLDOWN==180,"All Phase 2 gameplay values preserved");
  check(SpiritTreeTransformation.DURATION==180&&EndingCutscene.SLEIGH_DURATION==360&&BossFallPresentation.FANG_DURATION==240&&BossFallPresentation.TITAN_DURATION==300,"All approved cinematic timings unchanged");
  System.out.println("Phase2UITest PASS "+checks+" artwork/layout/input/preservation assertions");
 }
}
